    /// Every glyph, by case.
    ///
    /// A switch and not a dictionary: adding a case to `Icon` without adding its
    /// geometry here fails the build rather than rendering a blank slot.
    static func glyph(for icon: Icon) -> IconGlyph {
        switch icon {
        case .toolPen: Self.toolPen
        case .toolHighlighter: Self.toolHighlighter
        case .toolEraser: Self.toolEraser
        case .toolLasso: Self.toolLasso
        case .toolCenter: Self.toolCenter
        case .controlDock: Self.controlDock
        case .controlFull: Self.controlFull
        case .controlSettings: Self.controlSettings
        case .uiSelectionMarker: Self.uiSelectionMarker
        case .uiCheck: Self.uiCheck
        case .uiCross: Self.uiCross
        case .uiChevronDown: Self.uiChevronDown
        case .uiRetry: Self.uiRetry
        case .composerVoice: Self.composerVoice
        case .composerSend: Self.composerSend
        case .composerDismiss: Self.composerDismiss
        case .chipExplain: Self.chipExplain
        case .chipExample: Self.chipExample
        case .chipExercise: Self.chipExercise
        case .chipConfused: Self.chipConfused
        case .boardHinge: Self.boardHinge
        case .uiPlus: Self.uiPlus
        case .trailEye: Self.trailEye
        case .trailSearch: Self.trailSearch
        case .trailPlan: Self.trailPlan
        case .trailNote: Self.trailNote
        case .uiSidebarToggle: Self.uiSidebarToggle
        }
    }
}
